        headers = {
            "Authorization": f"Bearer {self.api_key}",
            "Content-Type": "application/json"
        }

        payload = {
            "model": self.model,
            "messages": self.history_manager.get_context_messages(),
            "temperature": 0.7,
            "max_tokens": 12000
        }

        # 如果有工具且启用工具调用，添加工具参数
